update public.content_blocks set value = '{"eyebrow":"Zu Hause · Hotel · Büro","title":"Du bleibst. Dein Profi kommt.","subtitle":"Geprüfte Profis für Massage, Nägel, Kosmetik, Haare und Make-up kommen zu dir – nach Hause, ins Hotel oder ins Büro.","cta":"Freie Termine finden"}'::jsonb, updated_at = now() where key = 'home.hero' and value = '{"eyebrow":"Wellness & Beauty bei Ihnen zu Hause","title":"Wellness, die zu Ihnen kommt.","subtitle":"Geprüfte Profis für Massage, Nägel, Kosmetik und Make-up – zu Hause, im Hotel oder im Büro. Wo dürfen wir Sie verwöhnen?","cta":"Verfügbare Profis anzeigen"}'::jsonb;
update public.content_blocks set value = '{"steps":[{"title":"Entdecken","body":"Finde deine Behandlung. PLZ, Behandlung, Zeitraum: Du siehst nur echte freie Termine – mit Endpreis inklusive Anfahrt."},{"title":"Buchen","body":"Wähl Ort und Uhrzeit – Zuhause, Hotel oder Büro. Bezahlt wird online, belastet erst nach dem Termin."},{"title":"Bleiben","body":"Dein Profi kommt zu dir. Mit deinem vierstelligen Start-Code beginnt der Termin."}]}'::jsonb, updated_at = now() where key = 'home.how_it_works' and value = '{"steps":[{"title":"Behandlung wählen","body":"Wählen Sie Ihre Wunschbehandlung und geben Sie Ihre Postleitzahl ein."},{"title":"Profi & Termin buchen","body":"Sie sehen nur echte freie Termine – mit Endpreis inklusive Anfahrt."},{"title":"Zurücklehnen","body":"Ihr Profi bringt alles mit. Sie genießen – wir kümmern uns um den Rest."}]}'::jsonb;
update public.content_blocks set value = '{"items":[{"q":"Wie funktioniert SOMA?","a":"Du gibst deine Postleitzahl ein und wählst eine Behandlung und einen Zeitraum. Du siehst geprüfte Profis mit echten freien Terminen und dem Endpreis inklusive Anfahrt. Du buchst – und dein Profi kommt zu dir nach Hause, ins Hotel oder ins Büro."},{"q":"Wie prüft SOMA die Profis?","a":"Bevor jemand buchbar ist, prüfen wir Ausweis, Gewerbeanmeldung und Berufshaftpflicht – und je nach Kategorie einen Qualifikationsnachweis, etwa eine Massageausbildung oder für Haare & Styling den Meisterbrief bzw. die Eintragung in die Handwerksrolle. Läuft ein Pflichtnachweis ab, pausieren wir das Profil. Bewerten kann nur, wer wirklich gebucht hat."},{"q":"Was kostet die Anfahrt?","a":"Die Anfahrt ist im Endpreis schon enthalten. Den Gesamtpreis siehst du in der Suche, bevor du buchst."},{"q":"Kann ich kostenlos stornieren?","a":"Bis 24 Stunden vor dem Termin stornierst du kostenlos, in den ersten 15 Minuten nach der Buchung sogar immer. Danach fallen gestaffelte Gebühren an; die genaue Frist siehst du vor dem Bezahlen – mit Datum und Uhrzeit."},{"q":"Wann wird meine Karte belastet?","a":"Bei der Buchung wird der Betrag nur reserviert. Belastet wird erst nach dem Termin. Bargeld gibt es nicht."},{"q":"Ist eine Massage auf SOMA eine medizinische Behandlung?","a":"Nein. Alle Angebote auf SOMA sind Beauty- und Wellnessanwendungen und ersetzen keine ärztliche, physiotherapeutische oder podologische Behandlung."},{"q":"Welche Anfragen sind ausgeschlossen?","a":"SOMA vermittelt ausschließlich Wellness- und Beautybehandlungen. Anzügliche Anfragen oder Bemerkungen führen zur Sperrung des Kontos."}]}'::jsonb, updated_at = now() where key = 'home.faq' and value = '{"items":[{"q":"Wie funktioniert SOMA?","a":"Sie wählen eine Behandlung, geben Ihre Postleitzahl ein und sehen geprüfte Profis mit echten freien Terminen. Nach der Buchung kommt Ihr Profi mit allem Nötigen zu Ihnen."},{"q":"Sind die Profis geprüft?","a":"Ja. Wir prüfen Ausweis, Gewerbeanmeldung, Berufshaftpflicht und – je nach Behandlung – Qualifikationsnachweise, bevor ein Profi buchbar ist."},{"q":"Was kostet die Anfahrt?","a":"Die Anfahrtskosten sind im angezeigten Endpreis bereits enthalten. Sie sehen den Gesamtpreis vor der Buchung."},{"q":"Kann ich kostenlos stornieren?","a":"Bis 24 Stunden vor dem Termin ist die Stornierung kostenlos. Danach fallen gestaffelte Gebühren an, die Ihnen vor der Buchung angezeigt werden."},{"q":"Wann wird meine Karte belastet?","a":"Bei der Buchung wird der Betrag nur reserviert. Belastet wird erst nach dem Termin."},{"q":"Sind die Massagen medizinische Behandlungen?","a":"Nein. Alle Massagen auf SOMA sind Wellnessanwendungen für Entspannung und Wohlbefinden und ersetzen keine ärztliche oder physiotherapeutische Behandlung."}]}'::jsonb;
